      [15]={sourceName="Tranquil Spirit",name="Tranquil Spirit",pos="e1",tier=5,col=1,icon="spell_holy_elunesgrace",maxRank=5,reqPoints=20,prereq=nil,arrows={},descriptions={[1]="Reduces the mana cost of your Healing Touch and Tranquility spells by 3%. In addition, increases effect and reduces threat caused by Tranquility by 20%.",[2]="Reduces the mana cost of your Healing Touch and Tranquility spells by 6%. In addition, increases effect and reduces threat caused by Tranquility by 40%.",[3]="Reduces the mana cost of your Healing Touch and Tranquility spells by 9%. In addition, increases effect and reduces threat caused by Tranquility by 60%.",[4]="Reduces the mana cost of your Healing Touch and Tranquility spells by 12%. In addition, increases effect and reduces threat caused by Tranquility by 80%.",[5]="Reduces the mana cost of your Healing Touch and Tranquility spells by 15%. In addition, increases effect and reduces threat caused by Tranquility by 100%."}},
      [16]={sourceName="Swiftmend",name="Swiftmend",pos="e2",tier=5,col=2,icon="inv_relics_idolofrejuvenation",maxRank=1,reqPoints=20,prereq=nil,arrows={},descriptions={[1]="Consumes a Rejuvenation or Regrowth effect on a friendly target to instantly heal them an amount equal to 12 sec. of Rejuvenation or 18 sec. of Regrowth."}},
