      [18]={sourceName="Animism",name="Animism",pos="f1",tier=6,col=1,icon="animism",maxRank=5,reqPoints=25,prereq=nil,arrows={},descriptions={[1]="Increases spell damage and healing by up to 10% of your total Spirit.",[2]="Increases spell damage and healing by up to 20% of your total Spirit.",[3]="Increases spell damage and healing by up to 30% of your total Spirit.",[4]="Increases spell damage and healing by up to 40% of your total Spirit.",[5]="Increases spell damage and healing by up to 50% of your total Spirit."}},
      [19]={sourceName="Improved Regrowth",name="Improved Regrowth",pos="f3",tier=6,col=3,icon="spell_nature_resistnature",maxRank=5,reqPoints=25,prereq="Improved Rejuvenation",arrows={{dir="down",from="d3",to="f3"},},descriptions={[1]="Increases the critical effect chance of your Regrowth spell by 15%.",[2]="Increases the critical effect chance of your Regrowth spell by 30%.",[3]="Increases the critical effect chance of your Regrowth spell by 45%.",[4]="Increases the critical effect chance of your Regrowth spell by 60%.",[5]="Increases the critical effect chance of your Regrowth spell by 75%."}},
