      [19]={sourceName="Lightning Reflexes",name="Lightning Reflexes",pos="f3",tier=6,col=3,icon="spell_nature_invisibilty",maxRank=5,reqPoints=25,prereq=nil,arrows={},descriptions={[1]="Increases your attack speed and Agility by 3%.",[2]="Increases your attack speed and Agility by 6%.",[3]="Increases your attack speed and Agility by 9%.",[4]="Increases your attack speed and Agility by 12%.",[5]="Increases your attack speed and Agility by 15%."}},
