      [18]={sourceName="Winter's Chill",name="Winter's Chill",pos="f3",tier=6,col=3,icon="spell_frost_chillingblast",maxRank=5,reqPoints=25,prereq=nil,arrows={},descriptions={[1]="Gives your Frost damage spells a 20% chance to apply the Winters Chill effect, which increases the chance a Frost spell will critically hit the target by 2% for 15 seconds. Stacks up to 10 times.",[2]="Gives your Frost damage spells a 40% chance to apply the Winters Chill effect, which increases the chance a Frost spell will critically hit the target by 2% for 15 seconds. Stacks up to 10 times.",[3]="Gives your Frost damage spells a 60% chance to apply the Winters Chill effect, which increases the chance a Frost spell will critically hit the target by 2% for 15 seconds. Stacks up to 10 times.",[4]="Gives your Frost damage spells a 80% chance to apply the Winters Chill effect, which increases the chance a Frost spell will critically hit the target by 2% for 15 seconds. Stacks up to 10 times.",[5]="Gives your Frost damage spells a 100% chance to apply the Winters Chill effect, which increases the chance a Frost spell will critically hit the target by 2% for 15 seconds. Stacks up to 10 times."}},
