      [10]={sourceName="Inner Light",name="Inner Light",pos="c2",tier=3,col=2,icon="spell_holy_surgeoflight",maxRank=1,reqPoints=10,prereq=nil,arrows={},descriptions={[1]="You emit a flash of blinding light and blind nearby enemies for 4 seconds. Targets must be facing you. Any damage caused will remove the effect."}},
      [11]={sourceName="Divine Grace",name="Divine Grace",pos="d1",tier=4,col=1,icon="spell_holy_sealofwisdom",maxRank=2,reqPoints=15,prereq=nil,arrows={},descriptions={[1]="Increases the effect of your Seal and Judgement of Light, your Seal and Judgement of Wisdom, you Blessing of Wisdom, and your Blessing of Light by 10%.\n\nIn addition, increases the duration and reduces the cost of your Blessing of Wisdowm and Blessing of Light by 50%.",[2]="Increases the effect of your Seal and Judgement of Light, your Seal and Judgement of Wisdom, you Blessing of Wisdom, and your Blessing of Light by 20%.\n\nIn addition, increases the duration and reduces the cost of your Blessing of Wisdowm and Blessing of Light by 100%."}},
      [12]={sourceName="Holy Grasp",name="Holy Grasp",pos="d2",tier=4,col=2,icon="spell_holy_healingaura",maxRank=3,reqPoints=15,prereq=nil,arrows={},descriptions={[1]="Increases the range of your Judgements, Exorcism, and Hammer of Wrath spells by 2 yards, increases the radius of your Holy Wrath by 3 yards, and reduces the cast time of your Holy Wrath and Hammer of Wrath spells by 0.5 sec.",[2]="Increases the range of your Judgements, Exorcism, and Hammer of Wrath spells by 4 yards, increases the radius of your Holy Wrath by 6 yards, and reduces the cast time of your Holy Wrath and Hammer of Wrath spells by 1 sec.",[3]="Increases the range of your Judgements, Exorcism, and Hammer of Wrath spells by 6 yards, increases the radius of your Holy Wrath by 9 yards, and reduces the cast time of your Holy Wrath and Hammer of Wrath spells by 1.5 sec."}},
      [13]={sourceName="Illumination",name="Illumination",pos="d3",tier=4,col=3,icon="spell_holy_greaterheal",maxRank=5,reqPoints=15,prereq="Holy Power",arrows={{dir="down",from="b3",to="d3"},},descriptions={[1]="After getting a critical effect from your Flash of Light, Holy Light, Holy Shock, Exorcism, Holy Wrath, or Hammer of Wrath spells, gives you a 20% chance to gain Mana equal to 50% of the base cost of the spell.",[2]="After getting a critical effect from your Flash of Light, Holy Light, Holy Shock, Exorcism, Holy Wrath, or Hammer of Wrath spells, gives you a 40% chance to gain Mana equal to 50% of the base cost of the spell.",[3]="After getting a critical effect from your Flash of Light, Holy Light, Holy Shock, Exorcism, Holy Wrath, or Hammer of Wrath spells, gives you a 60% chance to gain Mana equal to 50% of the base cost of the spell.",[4]="After getting a critical effect from your Flash of Light, Holy Light, Holy Shock, Exorcism, Holy Wrath, or Hammer of Wrath spells, gives you a 80% chance to gain Mana equal to 50% of the base cost of the spell.",[5]="After getting a critical effect from your Flash of Light, Holy Light, Holy Shock, Exorcism, Holy Wrath, or Hammer of Wrath spells, gives you a 100% chance to gain Mana equal to 50% of the base cost of the spell."}},
      [14]={sourceName="Unyielding Faith",name="Unyielding Faith",pos="d4",tier=4,col=4,icon="spell_holy_unyieldingfaith",maxRank=3,reqPoints=15,prereq=nil,arrows={},descriptions={[1]="Increases your chance to resist Fear and Disorient effects by an additional 10%.",[2]="Increases your chance to resist Fear and Disorient effects by an additional 20%.",[3]="Increases your chance to resist Fear and Disorient effects by an additional 30%."}},
      [15]={sourceName="Light's Mercy",name="Light's Mercy",pos="e1",tier=5,col=1,icon="spell_holy_holybolt",maxRank=5,reqPoints=20,prereq=nil,arrows={},descriptions={[1]="Gives your Flash of Light spells a 20% chance to apply the Spark of Light effect. Spark of light reduces the cast time of your next Holy Light by 10% and increases its range by 2 yards, the effect stacks up to 10 times.\nAlso increases the critical effect chance of your Flash of Light by 2%.",[2]="Gives your Flash of Light spells a 40% chance to apply the Spark of Light effect. Spark of light reduces the cast time of your next Holy Light by 10% and increases its range by 2 yards, the effect stacks up to 10 times.\nAlso increases the critical effect chance of your Flash of Light by 4%.",[3]="Gives your Flash of Light spells a 60% chance to apply the Spark of Light effect. Spark of light reduces the cast time of your next Holy Light by 10% and increases its range by 2 yards, the effect stacks up to 10 times.\nAlso increases the critical effect chance of your Flash of Light by 6%.",[4]="Gives your Flash of Light spells a 80% chance to apply the Spark of Light effect. Spark of light reduces the cast time of your next Holy Light by 10% and increases its range by 2 yards, the effect stacks up to 10 times.\nAlso increases the critical effect chance of your Flash of Light by 8%.",[5]="Gives your Flash of Light spells a 100% chance to apply the Spark of Light effect. Spark of light reduces the cast time of your next Holy Light by 10% and increases its range by 2 yards, the effect stacks up to 10 times.\nAlso increases the critical effect chance of your Flash of Light by 10%."}},
      [16]={sourceName="Holy Shock",name="Holy Shock",pos="e2",tier=5,col=2,icon="spell_holy_searinglight",maxRank=1,reqPoints=20,prereq=nil,arrows={},descriptions={[1]="Blasts the target with Holy energy, causing 134 Holy damage to an enemy, or 134 healing to an ally. Heals twice the amount on targets that have 20% or less health."}},
      [17]={sourceName="Improved Purifying",name="Improved Purifying",pos="e3",tier=5,col=3,icon="spell_holy_purifyingpower",maxRank=3,reqPoints=20,prereq=nil,arrows={},descriptions={[1]="Reduces the Mana cost of your Cleanse, Purify, Consecration, Exorcism, Holy Wrath and Hammer of Wrath spells by 15% and increases the critical strike chance of your Exorcism, Holy Wrath and Hammer of Wrath spells by 15%.",[2]="Reduces the Mana cost of your Cleanse, Purify, Consecration, Exorcism, Holy Wrath and Hammer of Wrath spells by 30% and increases the critical strike chance of your Exorcism, Holy Wrath and Hammer of Wrath spells by 30%.",[3]="Reduces the Mana cost of your Cleanse, Purify, Consecration, Exorcism, Holy Wrath and Hammer of Wrath spells by 45% and increases the critical strike chance of your Exorcism, Holy Wrath and Hammer of Wrath spells by 45%."}},
      [18]={sourceName="Healing Light",name="Healing Light",pos="f1",tier=6,col=1,icon="spell_holy_proclaimchampion",maxRank=5,reqPoints=25,prereq=nil,arrows={},descriptions={[1]="Increases the amount healed by your healing spells by 4% and reduces your Holy damage by 4%.",[2]="Increases the amount healed by your healing spells by 8% and reduces your Holy damage by 8%.",[3]="Increases the amount healed by your healing spells by 12% and reduces your Holy damage by 12%.",[4]="Increases the amount healed by your healing spells by 16% and reduces your Holy damage by 16%.",[5]="Increases the amount healed by your healing spells by 20% and reduces your Holy damage by 20%."}},
      [19]={sourceName="Searing Light",name="Searing Light",pos="f3",tier=6,col=3,icon="spell_holy_revivechampion",maxRank=5,reqPoints=25,prereq=nil,arrows={},descriptions={[1]="Increases you Holy damage by 4% and decreases healing done by 4%.",[2]="Increases you Holy damage by 8% and decreases healing done by 8%.",[3]="Increases you Holy damage by 12% and decreases healing done by 12%.",[4]="Increases you Holy damage by 16% and decreases healing done by 16%.",[5]="Increases you Holy damage by 20% and decreases healing done by 20%."}},
      [20]={sourceName="Holy Purge",name="Holy Purge",pos="g2",tier=7,col=2,icon="placeholder_icon",maxRank=1,reqPoints=30,prereq="Holy Shock",arrows={{dir="down",from="e2",to="g2"},},descriptions={[1]="10% chance on dealing Holy damage to dispel the enemy. In addition, deal/heal for 5% of your current mana for each dispelled effect on the enemy/ally."}},
    }},
    [2] = { name="Protection", key="Protection", background="protection", icon="spell_holy_devotionaura", talents={
      [1]={sourceName="Improved Hammer of Justice",name="Improved Hammer of Justice",pos="a1",tier=1,col=1,icon="spell_holy_sealofmight",maxRank=3,reqPoints=0,prereq=nil,arrows={},descriptions={[1]="Increases the duration of your Hammer of Justice spell by 0.5 sec and reduces its cooldown by 10%.",[2]="Increases the duration of your Hammer of Justice spell by 1 sec and reduces its cooldown by 20%.",[3]="Increases the duration of your Hammer of Justice spell by 1.5 sec and reduces its cooldown by 30%."}},
      [2]={sourceName="Toughness",name="Toughness",pos="a2",tier=1,col=2,icon="spell_holy_devotion",maxRank=5,reqPoints=0,prereq=nil,arrows={},descriptions={[1]="Increases your resistances and armor value from items by 2%.",[2]="Increases your resistances and armor value from items by 4%.",[3]="Increases your resistances and armor value from items by 6%.",[4]="Increases your resistances and armor value from items by 8%.",[5]="Increases your resistances and armor value from items by 10%."}},
      [3]={sourceName="Shield Specialization",name="Shield Specialization",pos="a3",tier=1,col=3,icon="inv_shield_06",maxRank=2,reqPoints=0,prereq=nil,arrows={},descriptions={[1]="Increases the amount of damage absorbed by your shield by 15%.",[2]="Increases the amount of damage absorbed by your shield by 30%."}},
      [4]={sourceName="Vindication",name="Vindication",pos="b1",tier=2,col=1,icon="spell_holy_vindication",maxRank=3,reqPoints=5,prereq=nil,arrows={},descriptions={[1]="Gives the Paladin's damaging melee attacks a chance to reduce the target's stats by 10% for 10 seconds.",[2]="Gives the Paladin's damaging melee attacks a chance to reduce the target's stats by 10% for 20 seconds.",[3]="Gives the Paladin's damaging melee attacks a chance to reduce the target's stats by 10% for 30 seconds."}},
      [5]={sourceName="Improved Defensive Auras",name="Improved Defensive Auras",pos="b2",tier=2,col=2,icon="spell_holy_devotionaura",maxRank=2,reqPoints=5,prereq=nil,arrows={},descriptions={[1]="Increases the armor and resistance bonus of your Devotion and Resistance auras by 25%.",[2]="Increases the armor and resistance bonus of your Devotion and Resistance auras by 50%."}},
      [6]={sourceName="Redoubt",name="Redoubt",pos="b3",tier=2,col=3,icon="ability_defend",maxRank=3,reqPoints=5,prereq="Shield Specialization",arrows={{dir="down",from="a3",to="b3"},},descriptions={[1]="Gives you a 20% chance when hit to gain a 10% chance to block attacks for 15 seconds of 5 blocks. Critical hits grants this effect five times more often.",[2]="Gives you a 20% chance when hit to gain a 20% chance to block attacks for 15 seconds of 5 blocks. Critical hits grants this effect five times more often.",[3]="Gives you a 20% chance when hit to gain a 30% chance to block attacks for 15 seconds of 5 blocks. Critical hits grants this effect five times more often."}},
      [7]={sourceName="Precision",name="Precision",pos="b4",tier=2,col=4,icon="ability_rogue_ambush",maxRank=5,reqPoints=5,prereq=nil,arrows={},descriptions={[1]="Increases your chance to hit with melee attack and spells by 1%.",[2]="Increases your chance to hit with melee attack and spells by 2%.",[3]="Increases your chance to hit with melee attack and spells by 3%.",[4]="Increases your chance to hit with melee attack and spells by 4%.",[5]="Increases your chance to hit with melee attack and spells by 5%."}},
      [8]={sourceName="Dominance",name="Dominance",pos="c1",tier=3,col=1,icon="spell_nature_reincarnation",maxRank=1,reqPoints=10,prereq="Vindication",arrows={{dir="down",from="b1",to="c1"},},descriptions={[1]="Degenerates the movement and attack capabilities of nearby opponents by 15%."}},
      [9]={sourceName="Improved Concentration Aura",name="Improved Concentration Aura",pos="c4",tier=3,col=4,icon="spell_holy_mindsooth",maxRank=3,reqPoints=10,prereq=nil,arrows={},descriptions={[1]="Increases the effect of your Concentration Aura by an additional 5% and gives all group members affected by the aura an additional 5% chance to resist Silence and Interrupt effects.",[2]="Increases the effect of your Concentration Aura by an additional 10% and gives all group members affected by the aura an additional 10% chance to resist Silence and Interrupt effects.",[3]="Increases the effect of your Concentration Aura by an additional 15% and gives all group members affected by the aura an additional 15% chance to resist Silence and Interrupt effects."}},
      [10]={sourceName="Second Wind",name="Second Wind",pos="c3",tier=3,col=3,icon="inv_jewelry_talisman_06",maxRank=5,reqPoints=10,prereq=nil,arrows={},descriptions={[1]="Restores mana equal to 4% of healing received.",[2]="Restores mana equal to 8% of healing received.",[3]="Restores mana equal to 12% of healing received.",[4]="Restores mana equal to 16% of healing received.",[5]="Restores mana equal to 20% of healing received."}},
      [11]={sourceName="Seal of Fury",name="Seal of Fury",pos="c2",tier=3,col=2,icon="spell_holy_crusader",maxRank=1,reqPoints=10,prereq=nil,arrows={},descriptions={[1]="Fills the Paladin with divine fury for 2 minutes, causing melee attacks to deal additional physical damage equal to 30% of normal weapon damage to 3 targets in front of the Paladin. Only one Seal can be active on the Paladin at any one time.\n\nUnleashing this Seal's energy will judge an enemy for 2 seconds, forcing the target to attack you. Has no effect if the target is already attacking you."}},
      [12]={sourceName="One-Handed Weapon Specialization",name="One-Handed Weapon Specialization",pos="d1",tier=4,col=1,icon="inv_sword_20",maxRank=5,reqPoints=15,prereq=nil,arrows={},descriptions={[1]="Increases the damage you deal with one-handed melee weapons by 2%.",[2]="Increases the damage you deal with one-handed melee weapons by 4%.",[3]="Increases the damage you deal with one-handed melee weapons by 6%.",[4]="Increases the damage you deal with one-handed melee weapons by 8%.",[5]="Increases the damage you deal with one-handed melee weapons by 10%."}},
      [13]={sourceName="Guardian's Favor",name="Guardian's Favor",pos="d3",tier=4,col=3,icon="spell_holy_sealofprotection",maxRank=2,reqPoints=15,prereq=nil,arrows={},descriptions={[1]="Increases the effect of your Blessing of Salvation and Blessing of Sanctuary by 10%. Also increases the duration and reduces the Mana cost of your Blessings of Freedom, Protection, Sacrifice, Salvation, and Sanctuary by 50%.",[2]="Increases the effect of your Blessing of Salvation and Blessing of Sanctuary by 20%. Also increases the duration and reduces the Mana cost of your Blessings of Freedom, Protection, Sacrifice, Salvation, and Sanctuary by 100%."}},
      [14]={sourceName="Unbreakability",name="Unbreakability",pos="d4",tier=4,col=4,icon="inv_shield_20",maxRank=3,reqPoints=15,prereq=nil,arrows={},descriptions={[1]="Decreases damage taken by 5%.",[2]="Decreases damage taken by 10%.",[3]="Decreases damage taken by 15%."}},
      [15]={sourceName="Divine Protection",name="Divine Protection",pos="e4",tier=5,col=4,icon="spell_holy_blessingofprotection",maxRank=1,reqPoints=20,prereq="Holy Shield",arrows={{dir="right",from="e3",to="e4"},},descriptions={[1]="Reduces all damage taken by 50%, but reduced damage caused by 30%. Lasts 10 sec."}},
      [16]={sourceName="Holy Shield",name="Holy Shield",pos="e3",tier=5,col=3,icon="spell_holy_blessingofprotection",maxRank=1,reqPoints=20,prereq=nil,arrows={},descriptions={[1]="Increases chance to block by 30% for 10 seconds, and deals 45 Holy damage for each attack blocked while active. Damage caused by Holy Shield causes twice additional threat. Each block expends a charge. 4 charges."}},
      [17]={sourceName="Improved Righteous Fury",name="Improved Righteous Fury",pos="e2",tier=5,col=2,icon="spell_holy_sealoffury",maxRank=3,reqPoints=20,prereq="Seal of Fury",arrows={{dir="down",from="c2",to="e2"},},descriptions={[1]="Increase the amount of threat generated while under the effect of Righteous Fury by 10% and increases your attack speed by 10%.",[2]="Increase the amount of threat generated while under the effect of Righteous Fury by 20% and increases your attack speed by 20%.",[3]="Increase the amount of threat generated while under the effect of Righteous Fury by 30% and increases your attack speed by 30%."}},
      [18]={sourceName="Morale",name="Morale",pos="f2",tier=6,col=2,icon="spell_holy_heroism",maxRank=5,reqPoints=25,prereq=nil,arrows={},descriptions={[1]="Increases your chance to resist Fear and Charm effects by 10%. In addition, your melee attacks have a 4% chance to restore 125 Mana.",[2]="Increases your chance to resist Fear and Charm effects by 20%. In addition, your melee attacks have a 8% chance to restore 125 Mana.",[3]="Increases your chance to resist Fear and Charm effects by 30%. In addition, your melee attacks have a 12% chance to restore 125 Mana.",[4]="Increases your chance to resist Fear and Charm effects by 40%. In addition, your melee attacks have a 16% chance to restore 125 Mana.",[5]="Increases your chance to resist Fear and Charm effects by 50%. In addition, your melee attacks have a 20% chance to restore 125 Mana."}},
      [19]={sourceName="Reckoning",name="Reckoning",pos="f1",tier=6,col=1,icon="spell_holy_blessingofstrength",maxRank=5,reqPoints=25,prereq="One-Handed Weapon Specialization",arrows={{dir="down",from="d1",to="f1"},},descriptions={[1]="Gives you a 4% chance to gain an extra attack after being hit by attacks or spells. The critical attacks have 5 times higher chance to grant an extra attack.",[2]="Gives you a 8% chance to gain an extra attack after being hit by attacks or spells. The critical attacks have 5 times higher chance to grant an extra attack.",[3]="Gives you a 12% chance to gain an extra attack after being hit by attacks or spells. The critical attacks have 5 times higher chance to grant an extra attack.",[4]="Gives you a 16% chance to gain an extra attack after being hit by attacks or spells. The critical attacks have 5 times higher chance to grant an extra attack.",[5]="Gives you a 20% chance to gain an extra attack after being hit by attacks or spells. The critical attacks have 5 times higher chance to grant an extra attack."}},
      [20]={sourceName="Stoicism",name="Stoicism",pos="g2",tier=7,col=2,icon="placeholder_icon",maxRank=1,reqPoints=30,prereq=nil,arrows={},descriptions={[1]="Delays your death by deferring all damage and healing for 3 seconds after a killing blow."}},
    }},
    [3] = { name="Retribution", key="Retribution", background="retribution", icon="spell_holy_auraoflight", talents={
      [1]={sourceName="Improved Judgement",name="Improved Judgement",pos="a1",tier=1,col=1,icon="spell_holy_righteousfury",maxRank=3,reqPoints=0,prereq=nil,arrows={},descriptions={[1]="Decreases the cooldown of your Judgement spells by 1 sec.",[2]="Decreases the cooldown of your Judgement spells by 2 sec.",[3]="Decreases the cooldown of your Judgement spells by 3 sec."}},
      [2]={sourceName="Conviction",name="Conviction",pos="a2",tier=1,col=2,icon="spell_holy_retributionaura",maxRank=5,reqPoints=0,prereq=nil,arrows={},descriptions={[1]="Increases your chance to get a critical strike with attacks and offensive spells by 1%.",[2]="Increases your chance to get a critical strike with attacks and offensive spells by 2%.",[3]="Increases your chance to get a critical strike with attacks and offensive spells by 3%.",[4]="Increases your chance to get a critical strike with attacks and offensive spells by 4%.",[5]="Increases your chance to get a critical strike with attacks and offensive spells by 5%."}},
      [3]={sourceName="Improved Seal of the Crusader",name="Improved Seal of the Crusader",pos="a3",tier=1,col=3,icon="spell_holy_holysmite",maxRank=3,reqPoints=0,prereq=nil,arrows={},descriptions={[1]="Increases the Holy damage and melee attack power bonuses of your Seal of the Crusader and the Holy damage increase of your Judgement of the Crusader by 5%.",[2]="Increases the Holy damage and melee attack power bonuses of your Seal of the Crusader and the Holy damage increase of your Judgement of the Crusader by 10%.",[3]="Increases the Holy damage and melee attack power bonuses of your Seal of the Crusader and the Holy damage increase of your Judgement of the Crusader by 15%."}},
      [4]={sourceName="Deflection",name="Deflection",pos="b1",tier=2,col=1,icon="ability_parry",maxRank=3,reqPoints=5,prereq=nil,arrows={},descriptions={[1]="Increases your Parry chance by 2%.",[2]="Increases your Parry chance by 4%.",[3]="Increases your Parry chance by 6%."}},
      [5]={sourceName="Pursuit of Justice",name="Pursuit of Justice",pos="b3",tier=2,col=3,icon="spell_holy_persuitofjustice",maxRank=2,reqPoints=5,prereq=nil,arrows={},descriptions={[1]="Increases the movement speed and mounted movement speed by 5%. This does not stack with other movement speed increasing effects.",[2]="Increases the movement speed and mounted movement speed by 10%. This does not stack with other movement speed increasing effects."}},
      [6]={sourceName="The Revenant",name="The Revenant",pos="c1",tier=3,col=1,icon="spell_holy_ashestoashes",maxRank=3,reqPoints=10,prereq="Deflection",arrows={{dir="down",from="b1",to="c1"},},descriptions={[1]="Reduces the chance you are critically hit by 2%.",[2]="Reduces the chance you are critically hit by 4%.",[3]="Reduces the chance you are critically hit by 6%."}},
      [7]={sourceName="Crusade",name="Crusade",pos="c2",tier=3,col=2,icon="spell_holy_crusade",maxRank=5,reqPoints=10,prereq="Conviction",arrows={{dir="down",from="a2",to="c2"},},descriptions={[1]="Increases spell damage and healing by up to 6% of your total Strength.",[2]="Increases spell damage and healing by up to 12% of your total Strength.",[3]="Increases spell damage and healing by up to 18% of your total Strength.",[4]="Increases spell damage and healing by up to 24% of your total Strength.",[5]="Increases spell damage and healing by up to 30% of your total Strength."}},
      [8]={sourceName="Seal of Command",name="Seal of Command",pos="c3",tier=3,col=3,icon="ability_warrior_innerrage",maxRank=1,reqPoints=10,prereq=nil,arrows={},descriptions={[1]="Gives the Paladin a chance to deal additional Holy damage equal to 50% of normal weapon damage. Only one Seal can be active on the Paladin at any one time. Lasts 30 seconds. Unleashing this Seal's energy will judge an enemy, instantly causing 0 Holy damage, 143 if the target is stunned, incapacitated or disoriented."}},
      [9]={sourceName="Improved Retribution Aura",name="Improved Retribution Aura",pos="c4",tier=3,col=4,icon="spell_holy_auraoflight",maxRank=2,reqPoints=10,prereq=nil,arrows={},descriptions={[1]="Increases the damage done by your Retribution Aura by 50% and deals an additional 5% of damage taken.",[2]="Increases the damage done by your Retribution Aura by 100% and deals an additional 10% of damage taken."}},
      [10]={sourceName="Eye for an Eye",name="Eye for an Eye",pos="d1",tier=4,col=1,icon="spell_holy_eyeforaneye",maxRank=2,reqPoints=15,prereq=nil,arrows={},descriptions={[1]="All spell hits against you cause 10% of the damage taken to the caster as well.",[2]="All spell hits against you cause 20% of the damage taken to the caster as well."}},
      [11]={sourceName="Benediction",name="Benediction",pos="d2",tier=4,col=2,icon="spell_frost_windwalkon",maxRank=3,reqPoints=15,prereq=nil,arrows={},descriptions={[1]="Reduces the cost of your Judgement and Seal spells by 10%.",[2]="Reduces the cost of your Judgement and Seal spells by 20%.",[3]="Reduces the cost of your Judgement and Seal spells by 30%."}},
      [12]={sourceName="Divine Might",name="Divine Might",pos="d3",tier=4,col=3,icon="spell_holy_fistofjustice",maxRank=2,reqPoints=15,prereq=nil,arrows={},descriptions={[1]="Increases the effect of your Blessing of Might and Blessing of Kings by 10%. Also increases their duration and reduces Mana cost by 50%.",[2]="Increases the effect of your Blessing of Might and Blessing of Kings by 20%. Also increases their duration and reduces Mana cost by 100%."}},
      [13]={sourceName="Two-Handed Weapon Specialization",name="Two-Handed Weapon Specialization",pos="e1",tier=5,col=1,icon="inv_hammer_04",maxRank=5,reqPoints=20,prereq=nil,arrows={},descriptions={[1]="Increases the damage you deal with two-handed melee weapons by 2%.",[2]="Increases the damage you deal with two-handed melee weapons by 4%.",[3]="Increases the damage you deal with two-handed melee weapons by 6%.",[4]="Increases the damage you deal with two-handed melee weapons by 8%.",[5]="Increases the damage you deal with two-handed melee weapons by 10%."}},
      [14]={sourceName="Sanctity Aura",name="Sanctity Aura",pos="e2",tier=5,col=2,icon="spell_holy_mindvision",maxRank=1,reqPoints=20,prereq=nil,arrows={},descriptions={[1]="Increases Holy damage done by party members within 30 yards by 10%. Players may only have one Aura on them per Paladin at any one time."}},
