      [10]={sourceName="Improved Corruption",name="Improved Corruption",pos="c4",tier=3,col=4,icon="spell_shadow_abominationexplosion",maxRank=5,reqPoints=10,prereq=nil,arrows={},descriptions={[1]="Reduces the Mana cost and threat caused by your Corruption spell by 6%.",[2]="Reduces the Mana cost and threat caused by your Corruption spell by 12%.",[3]="Reduces the Mana cost and threat caused by your Corruption spell by 18%.",[4]="Reduces the Mana cost and threat caused by your Corruption spell by 24%.",[5]="Reduces the Mana cost and threat caused by your Corruption spell by 30%."}},
      [11]={sourceName="Improved Drain Soul",name="Improved Drain Soul",pos="d1",tier=4,col=1,icon="spell_shadow_haunting",maxRank=2,reqPoints=15,prereq=nil,arrows={},descriptions={[1]="Reduces the cooldown of Drain Soul by 5 sec. Also gives you a 50% chance to get 10% increase to your Health and Mana regeneration over 20 seconds if the target is killed by you while you drain its soul. This effect stacks up to 5 times.",[2]="Reduces the cooldown of Drain Soul by 10 sec. Also gives you a 100% chance to get 10% increase to your Health and Mana regeneration over 20 seconds if the target is killed by you while you drain its soul. This effect stacks up to 5 times."}},
      [12]={sourceName="Nightfall",name="Nightfall",pos="d2",tier=4,col=2,icon="spell_shadow_twilight",maxRank=3,reqPoints=15,prereq=nil,arrows={},descriptions={[1]="Your periodic Shadow damage has a 1% chance to cause you to enter a Shadow Trance state.\n\nThe Shadow Trance state reduces the casting time of your next Shadow Bolt spell by 100%.\nCan occur once per 10 sec.",[2]="Your periodic Shadow damage has a 2% chance to cause you to enter a Shadow Trance state.\n\nThe Shadow Trance state reduces the casting time of your next Shadow Bolt spell by 100%.\nCan occur once per 10 sec.",[3]="Your periodic Shadow damage has a 3% chance to cause you to enter a Shadow Trance state.\n\nThe Shadow Trance state reduces the casting time of your next Shadow Bolt spell by 100%.\nCan occur once per 10 sec."}},
      [13]={sourceName="Herald of Woe",name="Herald of Woe",pos="d3",tier=4,col=3,icon="cloak_of_flame",maxRank=3,reqPoints=15,prereq="Amplify Curse",arrows={{dir="down",from="c3",to="d3"},},descriptions={[1]="Decreases the cooldown of your Amplify Curse, Death and Decay and Death Coil spells by 20%.",[2]="Decreases the cooldown of your Amplify Curse, Death and Decay and Death Coil spells by 40%.",[3]="Decreases the cooldown of your Amplify Curse, Death and Decay and Death Coil spells by 60%."}},
      [14]={sourceName="Siphon Life",name="Siphon Life",pos="e1",tier=5,col=1,icon="spell_shadow_requiem",maxRank=1,reqPoints=20,prereq=nil,arrows={},descriptions={[1]="Transfers 15 health from the target to the caster every 3 sec. Lasts 30 sec."}},
      [15]={sourceName="Withering Shroud",name="Withering Shroud",pos="e3",tier=5,col=3,icon="spell_shadow_callofbone",maxRank=2,reqPoints=20,prereq=nil,arrows={},descriptions={[1]="Afflicts nearby enemies with a disease that causes Shadow damage equal to 100% of your level every 4 sec. and slows their movement and attack speed by 5%. Lasts 12 sec.",[2]="Afflicts nearby enemies with a disease that causes Shadow damage equal to 200% of your level every 4 sec. and slows their movement and attack speed by 10%. Lasts 12 sec."}},
      [16]={sourceName="Death and Decay",name="Death and Decay",pos="e4",tier=5,col=4,icon="spell_shadow_deathanddecay",maxRank=1,reqPoints=20,prereq="Improved Corruption",arrows={{dir="down",from="c4",to="e4"},},descriptions={[1]="Invokes the malignant power of death and decay, reducing the effectiveness of any healing by 20% and inflicting Shadow damage equal to your level to nearby enemies every 2 seconds for 30 sec."}},
      [17]={sourceName="Shadow Mastery",name="Shadow Mastery",pos="f1",tier=6,col=1,icon="spell_shadow_shadetruesight",maxRank=5,reqPoints=25,prereq="Siphon Life",arrows={{dir="down",from="e1",to="f1"},},descriptions={[1]="Increases the damage dealt or life drained by your Shadow spells by 2%.",[2]="Increases the damage dealt or life drained by your Shadow spells by 4%.",[3]="Increases the damage dealt or life drained by your Shadow spells by 6%.",[4]="Increases the damage dealt or life drained by your Shadow spells by 8%.",[5]="Increases the damage dealt or life drained by your Shadow spells by 10%."}},
      [18]={sourceName="Inevitable Doom",name="Inevitable Doom",pos="f2",tier=6,col=2,icon="spell_shadow_auraofdarkness",maxRank=5,reqPoints=25,prereq="Nightfall",arrows={{dir="down",from="d2",to="f2"},},descriptions={[1]="Gives your Affliction spells an additional 5%  chance to resist dispel effects.\nAlso, it reduces the cooldown and duration of your Curse of Doom by 10%, increases its damage and reduces threat caused by 20%.",[2]="Gives your Affliction spells an additional 10%  chance to resist dispel effects.\nAlso, it reduces the cooldown and duration of your Curse of Doom by 20%, increases its damage and reduces threat caused by 40%.",[3]="Gives your Affliction spells an additional 15%  chance to resist dispel effects.\nAlso, it reduces the cooldown and duration of your Curse of Doom by 30%, increases its damage and reduces threat caused by 60%.",[4]="Gives your Affliction spells an additional 20%  chance to resist dispel effects.\nAlso, it reduces the cooldown and duration of your Curse of Doom by 40%, increases its damage and reduces threat caused by 80%.",[5]="Gives your Affliction spells an additional 25%  chance to resist dispel effects.\nAlso, it reduces the cooldown and duration of your Curse of Doom by 50%, increases its damage and reduces threat caused by 100%."}},
      [19]={sourceName="Prolonged Misery",name="Prolonged Misery",pos="f3",tier=6,col=3,icon="spell_shadow_unstableafllictions",maxRank=3,reqPoints=25,prereq=nil,arrows={},descriptions={[1]="Increases the duration of your Corruption, Curse of Agony and Immolate spells by 2 sec.",[2]="Increases the duration of your Corruption, Curse of Agony and Immolate spells by 4 sec.",[3]="Increases the duration of your Corruption, Curse of Agony Curse of Exhaustion and Immolate spells by 6 sec."}},
      [20]={sourceName="Defiler",name="Defiler",pos="g2",tier=7,col=2,icon="inevitabledoom",maxRank=1,reqPoints=30,prereq=nil,arrows={},descriptions={[1]="Reduces the time between periodic ticks and duration of your spells by 30% and reduces your global cooldown by 30%. In addition, your Drain spells affect an extra target."}},
