      [2]={sourceName="Improved Healthstone",name="Improved Healthstone",pos="a2",tier=1,col=2,icon="inv_stone_04",maxRank=2,reqPoints=0,prereq=nil,arrows={},descriptions={[1]="Increases the amount of Health restored by your Healthstone by 10%.",[2]="Increases the amount of Health restored by your Healthstone by 20%."}},
      [3]={sourceName="Unholy Power",name="Unholy Power",pos="a3",tier=1,col=3,icon="spell_shadow_shadowworddominate",maxRank=5,reqPoints=0,prereq=nil,arrows={},descriptions={[1]="Increases the damage done by your Imp, Voidwalker, Succubus and felhunter by 3%.",[2]="Increases the damage done by your Imp, Voidwalker, Succubus and felhunter by 6%.",[3]="Increases the damage done by your Imp, Voidwalker, Succubus and felhunter by 9%.",[4]="Increases the damage done by your Imp, Voidwalker, Succubus and felhunter by 12%.",[5]="Increases the damage done by your Imp, Voidwalker, Succubus and felhunter by 15%."}},
      [4]={sourceName="Improved Health Funnel",name="Improved Health Funnel",pos="a4",tier=1,col=4,icon="spell_shadow_lifedrain",maxRank=2,reqPoints=0,prereq=nil,arrows={},descriptions={[1]="Increases the effectiveness of your Health funnel spell by 25%.",[2]="Increases the effectiveness of your Health funnel spell by 50%."}},
      [5]={sourceName="Improved Voidwalker",name="Improved Voidwalker",pos="b1",tier=2,col=1,icon="spell_shadow_summonvoidwalker",maxRank=2,reqPoints=5,prereq=nil,arrows={},descriptions={[1]="Increases the effectiveness of your Voidwalker's Tormen, Consume Shadows, Sacrifice and Suffering spells by 15%.",[2]="Increases the effectiveness of your Voidwalker's Tormen, Consume Shadows, Sacrifice and Suffering spells by 30%."}},
      [6]={sourceName="Master Conjuror",name="Master Conjuror",pos="b2",tier=2,col=2,icon="spell_shadow_soulgem",maxRank=2,reqPoints=5,prereq=nil,arrows={},descriptions={[1]="Reduces the Mana cost and casting time of your Stone creation spells by 25% and increases the effectiveness of your Spellstones and Firestones by 25%.",[2]="Reduces the Mana cost and casting time of your Stone creation spells by 50% and increases the effectiveness of your Spellstones and Firestones by 50%."}},
      [7]={sourceName="Demonic Embrace",name="Demonic Embrace",pos="b3",tier=2,col=3,icon="spell_shadow_metamorphosis",maxRank=5,reqPoints=5,prereq=nil,arrows={},descriptions={[1]="The warlock regenerates 0.2% health every 2 seconds. In addition, increases the effect of Demon Armor and Demon Skin by 10%.",[2]="The warlock regenerates 0.4% health every 2 seconds. In addition, increases the effect of Demon Armor and Demon Skin by 20%.",[3]="The warlock regenerates 0.6% health every 2 seconds. In addition, increases the effect of Demon Armor and Demon Skin by 30%.",[4]="The warlock regenerates 0.8% health every 2 seconds. In addition, increases the effect of Demon Armor and Demon Skin by 40%.",[5]="The warlock regenerates 1% health every 2 seconds. In addition, increases the effect of Demon Armor and Demon Skin by 50%."}},
      [8]={sourceName="Damned Vanguard",name="Damned Vanguard",pos="b4",tier=2,col=4,icon="demonic_resilence",maxRank=2,reqPoints=5,prereq=nil,arrows={},descriptions={[1]="Decreases the damage taken by your demons by 10% and increases threat generated by them by 10%.",[2]="Decreases the damage taken by your demons by 20% and increases threat generated by them by 20%."}},
      [9]={sourceName="Improved Succubus",name="Improved Succubus",pos="c1",tier=3,col=1,icon="spell_shadow_summonsuccubus",maxRank=2,reqPoints=10,prereq=nil,arrows={},descriptions={[1]="Increases the effect of your Succubus' Lash of Pain and Soothing Kiss spells by 15% and increases the duration of your Succubus' Seduction and Lesser Invisibility spells by 15%.",[2]="Increases the effect of your Succubus' Lash of Pain and Soothing Kiss spells by 30% and increases the duration of your Succubus' Seduction and Lesser Invisibility spells by 30%."}},
      [10]={sourceName="Fel Domination",name="Fel Domination",pos="c2",tier=3,col=2,icon="spell_nature_removecurse",maxRank=1,reqPoints=10,prereq=nil,arrows={},descriptions={[1]="Your next Imp, Voidwalker, Succubus, or Felhunter Summon spell has its casting time reduced by 4 sec and its Mana cost reduced by 40%. In addition, reduces the casting time of your next Enslave Demon spell by up to 3 sec."}},
      [11]={sourceName="Demonic Onslaught",name="Demonic Onslaught",pos="c3",tier=3,col=3,icon="inv_misc_horn_02",maxRank=5,reqPoints=10,prereq=nil,arrows={},descriptions={[1]="Increases the melee and spell critical strike chance of your Imp, Voidwalker, Succubus, and felhunter by 4%.",[2]="Increases the melee and spell critical strike chance of your Imp, Voidwalker, Succubus, and felhunter by 8%.",[3]="Increases the melee and spell critical strike chance of your Imp, Voidwalker, Succubus, and felhunter by 12%.",[4]="Increases the melee and spell critical strike chance of your Imp, Voidwalker, Succubus, and felhunter by 16%.",[5]="Increases the melee and spell critical strike chance of your Imp, Voidwalker, Succubus, and felhunter by 20%."}},
      [12]={sourceName="Fel Intellect",name="Fel Intellect",pos="d1",tier=4,col=1,icon="spell_holy_magicalsentry",maxRank=5,reqPoints=15,prereq=nil,arrows={},descriptions={[1]="Increases the maximum Mana of your demons by 5% and your total Intellect by 5%.",[2]="Increases the maximum Mana of your demons by 10% and your total Intellect by 10%.",[3]="Increases the maximum Mana of your demons by 15% and your total Intellect by 15%.",[4]="Increases the maximum Mana of your demons by 20% and your total Intellect by 20%.",[5]="Increases the maximum Mana of your demons by 25% and your total Intellect by 25%."}},
      [13]={sourceName="Master Summoner",name="Master Summoner",pos="d2",tier=4,col=2,icon="spell_shadow_impphaseshift",maxRank=2,reqPoints=15,prereq="Fel Domination",arrows={{dir="down",from="c2",to="d2"},},descriptions={[1]="Reduces the casting time of your Imp, Voidwalker, Succubus, and Felhunter Summoning spells by 3 sec and the Mana cost by 30%",[2]="Reduces the casting time of your Imp, Voidwalker, Succubus, and Felhunter Summoning spells by 6 sec and the Mana cost by 60%"}},
      [14]={sourceName="Fel Stamina",name="Fel Stamina",pos="d4",tier=4,col=4,icon="spell_shadow_antishadow",maxRank=5,reqPoints=15,prereq=nil,arrows={},descriptions={[1]="Increases the maximum Health of your demons by 5% and your total Stamina by 5%.",[2]="Increases the maximum Health of your demons by 10% and your total Stamina by 10%.",[3]="Increases the maximum Health of your demons by 15% and your total Stamina by 15%.",[4]="Increases the maximum Health of your demons by 20% and your total Stamina by 20%.",[5]="Increases the maximum Health of your demons by 25% and your total Stamina by 25%."}},
      [15]={sourceName="Improved Felhunter",name="Improved Felhunter",pos="e1",tier=5,col=1,icon="spell_shadow_summonfelhunter",maxRank=2,reqPoints=20,prereq=nil,arrows={},descriptions={[1]="Increases the effectiveness of your Felhunter's Mana Burn and Paranoia spells by 15% and reduces the cooldown of your Felhunter's Devour Magic and Spell Lock spells by 15%.",[2]="Increases the effectiveness of your Felhunter's Mana Burn and Paranoia spells by 30% and reduces the cooldown of your Felhunter's Devour Magic and Spell Lock spells by 30%."}},
      [16]={sourceName="Soul Link",name="Soul Link",pos="e2",tier=5,col=2,icon="spell_shadow_gathershadows",maxRank=1,reqPoints=20,prereq=nil,arrows={},descriptions={[1]="When active, 20% of all damage taken by the caster is taken by your Imp, Voidwalker, Succubus, or Felhunter demon instead. In addition, the demon shares the master's stats, and both the demon and master will inflict 5% more damage. Lasts as long as the demon is active."}},
      [17]={sourceName="Improved Enslave Demon",name="Improved Enslave Demon",pos="e4",tier=5,col=4,icon="spell_shadow_enslavedemon",maxRank=2,reqPoints=20,prereq=nil,arrows={},descriptions={[1]="Reduces the Attack Speed penalty of your Enslave Demon spell by 20% and reduces the chance it will be resisted by 5%.",[2]="Reduces the Attack Speed penalty of your Enslave Demon spell by 40% and reduces the chance it will be resisted by 10%."}},
      [18]={sourceName="Master Demonologist",name="Master Demonilogist",pos="f1",tier=6,col=1,icon="spell_shadow_shadowpact",maxRank=5,reqPoints=25,prereq=nil,arrows={},descriptions={[1]="Grants both the Warlock and the summoned demon an effect as long as that demon is active.\n\nImp - Increases your critical strike chance by 3%.\n\nVoidwalker - Reduces physical physical damage taken by 3%.\n\nSuccubus - Increases all damage caused by 3%.\n\nFelhunter - Increases all resistances by 0.2 per level.",[2]="Grants both the Warlock and the summoned demon an effect as long as that demon is active.\n\nImp - Increases your critical strike chance by 6%.\n\nVoidwalker - Reduces physical physical damage taken by 6%.\n\nSuccubus - Increases all damage caused by 6%.\n\nFelhunter - Increases all resistances by 0.4 per level.",[3]="Grants both the Warlock and the summoned demon an effect as long as that demon is active.\n\nImp - Increases your critical strike chance by 9%.\n\nVoidwalker - Reduces physical physical damage taken by 9%.\n\nSuccubus - Increases all damage caused by 9%.\n\nFelhunter - Increases all resistances by 0.6 per level.",[4]="Grants both the Warlock and the summoned demon an effect as long as that demon is active.\n\nImp - Increases your critical strike chance by 12%.\n\nVoidwalker - Reduces physical physical damage taken by 12%.\n\nSuccubus - Increases all damage caused by 12%.\n\nFelhunter - Increases all resistances by 0.8 per level.",[5]="Grants both the Warlock and the summoned demon an effect as long as that demon is active.\n\nImp - Increases your critical strike chance by 15%.\n\nVoidwalker - Reduces physical physical damage taken by 15%.\n\nSuccubus - Increases all damage caused by 15%.\n\nFelhunter - Increases all resistances by 1 per level."}},
      [19]={sourceName="Fel Pact",name="Fel Pact",pos="f3",tier=6,col=3,icon="inv_helmet_08",maxRank=5,reqPoints=25,prereq="Demonic Onslaught",arrows={{dir="down",from="c3",to="f3"},},descriptions={[1]="Demon's critical hits from a spell or abilities have a 8% chance to regenerate 15% of your total Mana over 15 sec. In addition your spell casts have a 2% chance to regenerate 30% of demon's total Health over 15 seconds.",[2]="Demon's critical hits from a spell or abilities have a 16% chance to regenerate 15% of your total Mana over 15 sec. In addition your spell casts have a 4% chance to regenerate 30% of demon's total Health over 15 seconds.",[3]="Demon's critical hits from a spell or abilities have a 24% chance to regenerate 15% of your total Mana over 15 sec. In addition your spell casts have a 6% chance to regenerate 30% of demon's total Health over 15 seconds.",[4]="Demon's critical hits from a spell or abilities have a 32% chance to regenerate 15% of your total Mana over 15 sec. In addition your spell casts have a 8% chance to regenerate 30% of demon's total Health over 15 seconds.",[5]="Demon's critical hits from a spell or abilities have a 40% chance to regenerate 15% of your total Mana over 15 sec. In addition your spell casts have a 10% chance to regenerate 30% of demon's total Health over 15 seconds."}},
      [20]={sourceName="Demonic Sacrifice",name="Demonic Sacrifice",pos="g2",tier=7,col=2,icon="spell_shadow_psychicscream",maxRank=1,reqPoints=30,prereq="Soul Link",arrows={{dir="down",from="e2",to="g2"},},descriptions={[1]="When activated, sacrifices your summoned demon to grant you an effect based on demon's type.\n\nImp: Shifts you out of phase with the world for 10 seconds and reduces your threat caused by 30% for 5 mins.\n\nVoidwalker: Shielding nearby group members, absorbing 1151 damage for 30 seconds and restores 3% of your total Health every 3 sec for 5 min.\n\nSuccubus: Increases attack and casting speed of nearby group members by 5% for 30 seconds and increases your damage by 5% for 5 min.\n\nFelhunter: Protects nearby group members from all spells for 3 seconds and restores 3% of your total Mana every 3 sec for 5 min."}},
    }},
    [3] = { name="Destruction", key="Destruction", background="destruction", icon="spell_shadow_rainoffire", talents={
