      [9]={sourceName="Feeding Demons",name="Feeding Demons",pos="c3",tier=3,col=3,icon="dragon_devour",maxRank=2,reqPoints=10,prereq="Demonic Power",arrows={{dir="down",from="b3",to="c3"},},descriptions={[1]="Your spell critical strikes have a 50% chance to restore 6 per level Mana to your demon.",[2]="Your spell critical strikes have a 100% chance to restore 6 per level Mana to your demon."}},
