local TalentInspectData_ClassMap = {
  ["DRUID"]="DRUID", ["Druid"]="DRUID",
  ["HUNTER"]="HUNTER", ["Hunter"]="HUNTER",
  ["MAGE"]="MAGE", ["Mage"]="MAGE",
  ["PALADIN"]="PALADIN", ["Paladin"]="PALADIN",
  ["PRIEST"]="PRIEST", ["Priest"]="PRIEST",
  ["ROGUE"]="ROGUE", ["Rogue"]="ROGUE",
  ["SHAMAN"]="SHAMAN", ["Shaman"]="SHAMAN",
  ["WARLOCK"]="WARLOCK", ["Warlock"]="WARLOCK",
  ["WARRIOR"]="WARRIOR", ["Warrior"]="WARRIOR",
}

function TalentInspectData_NormalizeClass(classToken)
  if not classToken then return nil end
  if TalentInspectData_ClassMap[classToken] then
    return TalentInspectData_ClassMap[classToken]
  end
  local upper=string.upper(tostring(classToken))
  if TalentInspectData and TalentInspectData[upper] then return upper end
  return classToken
end

function TalentInspectData_GetTree(classToken, treeIndex)
  classToken=TalentInspectData_NormalizeClass(classToken)
  local c=TalentInspectData and TalentInspectData[classToken]
  return c and c.trees and c.trees[treeIndex]
end

local function TalentInspectData_GetLearnedTree(classToken,treeIndex)
  classToken=TalentInspectData_NormalizeClass(classToken)
  local learned=TalentInspectData_Learned and TalentInspectData_Learned[classToken]
  return learned and learned.trees and learned.trees[treeIndex] or nil
end

local function TalentInspectData_MergeTalent(staticTalent,learnedTalent)
  if not learnedTalent then return staticTalent end
  local out={}
  if staticTalent then
    for k,v in pairs(staticTalent) do out[k]=v end
  end
  -- Live scan is authoritative for fields it actually observed.
  for k,v in pairs(learnedTalent) do
    if v~=nil then out[k]=v end
  end

  -- FR4k: successful live prerequisite scan is authoritative INCLUDING absence.
  if learnedTalent.prereqScanned==1 then
    out.preTier=learnedTalent.preTier
    out.preCol=learnedTalent.preCol
    out.preRank=learnedTalent.preRank
    out.prereq=nil
    out.prereqScanned=1
  end

  out.learned=1
  return out
end

function TalentInspectData_FindTalent(classToken, treeIndex, name, pos, index)
  classToken=TalentInspectData_NormalizeClass(classToken)
  local tree=TalentInspectData_GetTree(classToken,treeIndex)
  local learnedTree=TalentInspectData_GetLearnedTree(classToken,treeIndex)

  -- HARD IDENTITY RULE:
  -- Once the live client gives us a talent NAME, only that exact name may
  -- satisfy the lookup. A stale position/index must never turn Divine
  -- Protection into Improved Holy Shield.
  if name and name~="" then
    if learnedTree and learnedTree.byName and learnedTree.byName[name] then
      local live=learnedTree.byName[name]
      local static=nil
      if tree then
        for _,t in pairs(tree.talents) do
          if t.name==name or t.sourceName==name then static=t; break end
        end
      end
      return TalentInspectData_MergeTalent(static,live)
    end

    if tree then
      for _,t in pairs(tree.talents) do
        if t.name==name or t.sourceName==name then return t end
      end
    end

    -- Exact live identity exists but our databases do not know it yet.
    -- Return nil rather than lying with a different talent from this slot.
    return nil
  end

  -- Geometry/index are allowed only when no live identity was supplied
  -- (principally static/zero-tree compatibility paths).
  if learnedTree then
    if pos and learnedTree.byPos and learnedTree.byPos[pos] then
      local live=learnedTree.byPos[pos]
      local static=nil
      if tree then
        for _,t in pairs(tree.talents) do
          if t.name==live.name or t.sourceName==live.name then static=t; break end
        end
      end
      return TalentInspectData_MergeTalent(static,live)
    end
    if index and learnedTree.talents and learnedTree.talents[index] then
      return TalentInspectData_MergeTalent(nil,learnedTree.talents[index])
    end
  end

  if not tree then return nil end
  if pos then
    for _,t in pairs(tree.talents) do
      if t.pos==pos then return t end
    end
  end
  if index and tree.talents[index] then return tree.talents[index] end
  return nil
end

function TalentInspectData_GetLearnedClass(classToken)
  classToken=TalentInspectData_NormalizeClass(classToken)
  return TalentInspectData_Learned and TalentInspectData_Learned[classToken] or nil
end


-- FR4f: SINGLE description authority path for the entire addon.
-- Every UI consumer (inspect tooltip, talent links, future views) should call
-- this rather than reading .desc or .descriptions directly.
function TalentInspectData_GetDescription(talent, rank)
  if not talent then return nil,"none" end
  rank=tonumber(rank) or 1
  if rank<1 then rank=1 end

  local maxRank=tonumber(talent.maxRank) or 1
  if rank>maxRank then rank=maxRank end

  local descRank=tonumber(talent.descRank)

  -- Absolute authority: a live-scanned/peer-learned description explicitly
  -- identified as the rank being requested.
  if talent.desc and talent.desc~="" then
    if descRank==rank then
      return talent.desc,"learned"
    end

    -- Single-rank talents are unambiguous even for pre-FR4e learned caches that
    -- lacked descRank.
    if maxRank==1 and (not descRank or descRank==1) then
      return talent.desc,"learned"
    end
  end

  -- Packaged rank-specific baseline only after Learned Data cannot answer the
  -- requested rank exactly.
  if talent.descriptions and talent.descriptions[rank] then
    return talent.descriptions[rank],"static"
  end

  return nil,"none"
end


-- FR4k: prerequisite authority resolver.
function TalentInspectData_GetPrerequisite(talent)
  if not talent then return nil,nil,nil,"none" end
  if talent.prereqScanned==1 then
    if talent.preTier and talent.preCol and talent.preTier>0 and talent.preCol>0 then
      return talent.preTier,talent.preCol,talent.preRank,"learned"
    end
    return nil,nil,nil,"learned-none"
  end
  if talent.preTier and talent.preCol and talent.preTier>0 and talent.preCol>0 then
    return talent.preTier,talent.preCol,talent.preRank,"legacy"
  end
  return nil,nil,nil,"none"
end
